package com.mamtrex.hospital.pharmacy;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/drugs") public class DrugController { private final DrugRepository repo; private final AuditService audit; public DrugController(DrugRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String code, @jakarta.validation.constraints.NotBlank String genericName, @jakarta.validation.constraints.NotBlank String brandName, @jakarta.validation.constraints.NotBlank String strength, @jakarta.validation.constraints.NotBlank String stockQuantity){} @PostMapping public Drug create(@Valid @RequestBody Request r){var e=repo.save(new Drug(r.code(), r.genericName(), r.brandName(), r.strength(), r.stockQuantity()));audit.record("CREATE","Drug",e.getId().toString(),"created");return e;} @GetMapping public List<Drug> list(){return repo.findAll();} @GetMapping("/{id}") public Drug get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Drug not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("Drug not found: "+id);repo.deleteById(id);audit.record("DELETE","Drug",id.toString(),"deleted");} }
